    original: "\u092f\u0915\u094d\u0937\u0938\u094d\u0935\u0930\u0942\u092a\u093e\u092f \u091c\u091f\u093e\u0927\u0930\u093e\u092f \u092a\u093f\u0928\u093e\u0915\u0939\u0938\u094d\u0924\u093e\u092f \u0938\u0928\u093e\u0924\u0928\u093e\u092f \u0964\n\u0926\u093f\u0935\u094d\u092f\u093e\u092f \u0926\u0947\u0935\u093e\u092f \u0926\u093f\u0917\u092e\u094d\u092c\u0930\u093e\u092f \u0924\u0938\u094d\u092e\u0948 \u092f\u0915\u093e\u0930\u093e\u092f \u0928\u092e\u0903 \u0936\u093f\u0935\u093e\u092f \u0965",
